import java.util.*;public class TestMain{static void eq(long a,long b){if(a!=b)throw new AssertionError(a+" != "+b);}public static void main(String[]a){InvoiceCalculator c=new InvoiceCalculator();eq(c.totalCents(new Invoice(List.of(new Line("19.995",1)))),2000);eq(c.totalCents(new Invoice(List.of(new Line("10.005",1)))),1000);eq(c.totalCents(new Invoice(List.of(new Line("0.335",3)))),100);eq(c.totalCents(new Invoice(List.of(new Line("1.002",1),new Line("1.004",1)))),201);try{c.totalCents(new Invoice(List.of(new Line("x",1))));throw new AssertionError();}catch(IllegalArgumentException e){}System.out.println("OK");}}
